// Fixture access and case data for the StreamingAudio contract tests. The fixtures and their
// manifest are generated by Plugins/StreamingAudio/Tests/Fixtures/generate.py and copied into the host's Fixtures folder.
namespace AudioCases
{
	/** Fixtures that decode, and the one with a corrupted middle frame. */
	inline const TArray<FString>& DecodableFixtures()
	{
		static const TArray<FString> Names = {
			TEXT("mpeg1_cbr_stereo_44k.mp3"), TEXT("mpeg1_cbr_mono_44k.mp3"), TEXT("mpeg2_cbr_mono_22k.mp3"),
			TEXT("mpeg25_cbr_mono_8k.mp3"), TEXT("mpeg1_vbr_stereo_44k.mp3"),
		};
		return Names;
	}
	inline const TCHAR* StereoFixture() { return TEXT("mpeg1_cbr_stereo_44k.mp3"); }
	inline const TCHAR* MonoMpeg2Fixture() { return TEXT("mpeg2_cbr_mono_22k.mp3"); }
	inline const TCHAR* CorruptedFixture() { return TEXT("mpeg1_cbr_stereo_44k_corrupt.mp3"); }
	inline const TCHAR* Layer2Fixture() { return TEXT("layer2_stereo_44k.mp2"); }
	inline const TCHAR* Layer1HeaderFixture() { return TEXT("layer1_header.bin"); }
	inline const TCHAR* FreeFormatHeaderFixture() { return TEXT("free_format_header.bin"); }
	inline const TCHAR* Wav16Fixture() { return TEXT("pcm16_mono_16k.wav"); }
	inline const TCHAR* WavExtensibleFixture() { return TEXT("pcm16_extensible_stereo_44k.wav"); }
	inline const TCHAR* Wav24Fixture() { return TEXT("pcm24_stereo_44k.wav"); }

	constexpr int32 FragmentBytes = 1024;
	constexpr int32 SmallSyncWindowBytes = 4 * 1024;
	constexpr int32 TruncatedTailBytes = 100;
	/** Frames the decoder may lose around the corrupted frame while it resynchronises. */
	constexpr int32 MaxFramesLostToCorruption = 4;
	constexpr int32 HandoffCycles = 1000;

	inline FString FixturePath(const FString& Name)
	{
		return FPaths::Combine(FPaths::ProjectDir(), TEXT("Fixtures"), Name);
	}

	inline TArray<uint8> LoadFixture(const FString& Name)
	{
		TArray<uint8> Bytes;
		FFileHelper::LoadFileToArray(Bytes, *FixturePath(Name));
		return Bytes;
	}

	inline TSharedPtr<FJsonObject> Manifest()
	{
		FString Text;
		TSharedPtr<FJsonObject> Root;
		if (FFileHelper::LoadFileToString(Text, *FixturePath(TEXT("manifest.json"))))
		{
			FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root);
		}
		return Root;
	}

	/** Expected decoded PCM size of an audio fixture, from the manifest. */
	inline int64 ExpectedPcmBytes(const FJsonObject& Entry, int32 FramesLess = 0)
	{
		return static_cast<int64>(Entry.GetIntegerField(TEXT("frames")) - FramesLess)
			* Entry.GetIntegerField(TEXT("samples_per_frame")) * Entry.GetIntegerField(TEXT("channels")) * FStreamingAudioFormat::BytesPerSample;
	}

	/** Interleaved 16-bit PCM with a distinct value in every sample, so reordering is visible. */
	inline TArray<uint8> Ramp(const FStreamingAudioFormat& Format, int32 Frames, int32 Seed = 0)
	{
		TArray<uint8> Bytes;
		Bytes.SetNumUninitialized(Frames * Format.GetBytesPerFrame());
		int16* Samples = reinterpret_cast<int16*>(Bytes.GetData());
		for (int32 Index = 0; Index < Frames * Format.NumChannels; ++Index)
		{
			Samples[Index] = static_cast<int16>((Index * 7 + Seed * 131) % 30000 - 15000);
		}
		return Bytes;
	}

	inline FStreamingAudioFormat MakeFormat(int32 SampleRate, int32 NumChannels)
	{
		FStreamingAudioFormat Format;
		Format.SampleRate = SampleRate;
		Format.NumChannels = NumChannels;
		return Format;
	}
}
